(() => {
  const sites = {"portfolio": {"label": "Luke Stilson", "url": "https://lukestilson.com"}, "plush": {"label": "Plush", "url": "https://plushengine.com"}, "openvat": {"label": "OpenVAT", "url": "https://openvat.org"}};
  const local = ['localhost', '127.0.0.1', '::1', '[::1]'].includes(location.hostname) || location.protocol === 'file:';
  const source = new URL(document.currentScript.src);
  for (const a of document.querySelectorAll('a[data-site]')) {
    const site = sites[a.dataset.site];
    if (!site) continue;
    const path = a.dataset.sitePath || '';
    a.href = local ? new URL('../../' + a.dataset.site + '/' + (path || 'index.html'), source).href : site.url.replace(/\/$/, '') + '/' + path;
  }
})();
